import React, { useMemo } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { getLegendOrientation } from '../../core/components/chart-layout/functions/orientation.js';
import { useChartLayoutOrientation } from '../../core/components/chart-layout/hooks/useChartLayoutOrientation.js';
import { ChartLegend } from '../../core/components/legend/categorical/ChartLegend.js';
import { useLegendSeriesActions } from '../../core/components/legend/categorical/hooks/useLegendSeriesActions.js';
import { LegendItem } from '../../core/components/legend/categorical/types/legend.js';
import { useTreeMapData } from '../context/TreeMapDataContext.js';
import { useTruncationMode } from '../hooks/useTruncationMode.js';
import { useTooltipPinnedState } from '../store/selectors.js';

type TreeMapLegendProps = {
  onHover: (hoveredSeries?: LegendItem[]) => void;
  onClick: (visibleSlices: LegendItem[]) => void;
};

export const TreemapLegend = (props: TreeMapLegendProps): JSX.Element => {
  const { onHover, onClick } = props;
  const data = useTreeMapData();

  const { orientation: layoutOrientation } = useChartLayoutOrientation();
  const legendOrientation = getLegendOrientation(layoutOrientation);
  const truncationMode = useTruncationMode();
  const isTooltipPinned = useTooltipPinnedState();

  // map first level of tree items to legend items and filter out branches with zero values
  const legendItems = useMemo(
    () =>
      data.tree?.children
        ?.filter((node) => node.value > 0)
        .map((node) => ({
          id: node.name ?? '',
          color: node.color ?? Colors.Charts.Categorical.Color01,
          name: node.name ?? '',
        })),
    [data],
  );

  const legendActions = useLegendSeriesActions<LegendItem>(
    legendItems ?? [],
    (item) => item.id,
  );

  const chartLegendInteractionsProps = isTooltipPinned
    ? { interactionsDisabled: true }
    : {
        onSeriesAction: legendActions,
        onHover: onHover,
        onClick: onClick,
        interactionsDisabled: false,
      };

  return (
    <ChartLegend
      items={legendItems ?? []}
      truncationMode={truncationMode}
      orientation={legendOrientation}
      {...chartLegendInteractionsProps}
    />
  );
};

TreemapLegend.displayName = 'TreemapLegend';
